from agent import *from models.products import *def run(context: dict[str, str], session: Session):    session.sessionbreakers = [SessionBreak(max_requests=4000)]    session.queue(Request("https://www.westpark-gamers.de/Reviews/gametable.php?ind=0&si=0", use="curl", max_age=7), process_category, dict())def process_category(data: Response, context: dict[str, str], session: Session):    rows = data.xpath("//div[@id='content']/table/tr[not(@align)]")    for row in rows:        name = row.xpath("td[1]/text()").string()        prod_url = row.xpath("td[1]/a/@href").string()        brand = row.xpath("td[3]/text()").string()        session.queue(Request(prod_url, use="curl", max_age=7), process_revlist, dict(name=name, prod_url=prod_url, brand=brand))    next_url = data.xpath("//ul[@id='tabmenu']/li[a[@class='active']]/following-sibling::li[1]/a/@href").string()    if next_url:        session.queue(Request(next_url, use="curl", max_age=7), process_category, dict())def process_revlist(data: Response, context: dict[str, str], session: Session):    overall = len(data.xpath("//img[@alt='red star']"))    revs = data.xpath("//table/tr[th[text()='Reviews']]/td/a")    for rev in revs:        url = rev.xpath("@href").string()        if ".pdf" in url:            continue        info = rev.xpath("following-sibling::text()").string()        date = info.split(')')[0].split('(')[-1]        author = info.split(" by ")[-1]        session.queue(Request(url, use="curl", max_age=7), process_review, dict(context, date=date, author=author, url=url, overall=overall))def process_review(data: Response, context: dict[str, str], session: Session):    product = Product()    product.name = context["name"]    product.url = context["prod_url"]    product.ssid = product.url.split('/')[-1].split("gameid=")[-1]    product.category = "Board Games"    product.manufacturer = context["brand"]    review = Review()    review.type = "pro"    review.url = context["url"]    review.title = context["name"]    review.ssid = review.url.split('/')[-1].split(".")[0].split("bericht")[-1].split('?p=')[-1]    if not review.ssid:        review.ssid = review.url.split('/')[-2]    review.date = context["date"]    if context.get("overall"):        review.grades.append(Grade(type='overall', value=int(context["overall"]), best=10))    author = data.xpath("//p/i[regexp:test(text(), '^rezensiert von ', 'i')]/text()").string()    if author:        author = author.split("rezensiert von ")[-1]        review.authors.append(Person(name=author, ssid=author))    elif context.get("author"):        review.authors.append(Person(name=context["author"], ssid=context["author"]))    excerpt = data.xpath("//div[@class='entry-content']/*[self::p or self::ul][not(@*) and not(i[regexp:test(text(), '^rezensiert von ', 'i')])]//text()").string(multiple=True)    if not excerpt:        excerpt = data.xpath("//*[self::p[not(@*) and not(i[regexp:test(text(), '^rezensiert von ', 'i')])] or self::ul or self::ol][not(regexp:test(., 'autor:|am tisch:|auf dem tisch:', 'i'))]//text()").string(multiple=True)    if excerpt:        if "originally published" in excerpt:            return        review.add_property(type="excerpt", value=excerpt)        product.reviews.append(review)        session.emit(product)